/**
 * Card-game icons, built on lucide.
 *
 * The kit's icon set (@glacier/icons, a proxy over lucide-react) is a general
 * UI vocabulary - it has no glyph for a booster pack, a fanned hand, or a deck,
 * so those were drawn for us. They are declared through lucide's own
 * `createLucideIcon`, which means they are lucide icons in every way that
 * matters: same `size`/`color`/`strokeWidth`/`absoluteStrokeWidth` props, same
 * `currentColor` inheritance, same `lucide lucide-<name>-icon` classes, so they
 * drop in anywhere a kit icon goes and line up with the ones beside them.
 *
 * Two things to know when reaching for these:
 *  - `PlayingCardDeck` was drawn as an outline (filled paths, no stroke), so it
 *    ignores `strokeWidth`. At the sizes the app uses it matches the 2px set;
 *    at strokeWidth={1} it will read heavier than its neighbours.
 *  - `PlayingCardStack` came in a 17x24 box and is translated to centre it in
 *    24x24 rather than scaled, so its stroke stays 2px like everything else.
 *    It fills slightly more of the box than the rest of the set.
 *
 * Path data is otherwise verbatim from the source SVGs.
 */
import { createLucideIcon } from 'lucide-react';

export type { IconProps } from '@glacier/icons';

